const storage = (() => {
  try { localStorage.setItem("__t", "1"); localStorage.removeItem("__t"); return localStorage }
  catch { const m = {}; return { getItem: (k) => (k in m ? m[k] : null), setItem: (k, v) => { m[k] = String(v) } } }
})()
let expenses = JSON.parse(storage.getItem("expenses") ?? "[]")
const form = document.querySelector("#expense")
const list = document.querySelector("#list")
const total = document.querySelector("#total")
const error = document.querySelector("#error")
const naira = (n) => "₦" + n.toLocaleString("en-NG")

function render() {
  list.innerHTML = ""
  expenses.forEach((e, i) => {
    const li = document.createElement("li")
    li.textContent = `${e.item} (${e.category}): ${naira(e.amount)} `
    const del = document.createElement("button")
    del.textContent = "Delete"
    del.addEventListener("click", () => {
      expenses = expenses.filter((_, j) => j !== i)
      update()
    })
    li.append(del)
    list.append(li)
  })
  total.textContent = naira(expenses.reduce((s, e) => s + e.amount, 0))
}
function update() {
  storage.setItem("expenses", JSON.stringify(expenses))
  render()
}
form.addEventListener("submit", (ev) => {
  ev.preventDefault()
  const item = form.elements.item.value.trim()
  const amount = Number(form.elements.amount.value)
  if (form.elements.amount.value.trim() === "" || !(amount > 0)) {
    error.textContent = "Please enter an amount above 0"
    return
  }
  error.textContent = ""
  expenses = [...expenses, { item, amount, category: form.elements.category.value }]
  form.reset()
  update()
})
render()
